<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('billing.charges.view');
$pageTitle='Próximos cobros';$pdo=db();billing_refresh_overdue_charges();
$view=(string)($_GET['view']??'all');$clientId=max(0,(int)($_GET['client_id']??0));$serviceId=max(0,(int)($_GET['service_id']??0));$currency=(string)($_GET['currency']??'');$q=trim((string)($_GET['q']??''));$where=[];$params=[];
$views=['upcoming'=>"bc.status IN ('pending','partial') AND bc.due_date>=CURDATE()",'week'=>"bc.status IN ('pending','partial') AND bc.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)",'month'=>"bc.status IN ('pending','partial') AND bc.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY)",'overdue'=>"bc.status='overdue'",'paid'=>"bc.status='paid'",'all'=>'1=1'];if(!isset($views[$view]))$view='all';$where[]=$views[$view];
if($clientId){$where[]='bc.client_id=?';$params[]=$clientId;}if($serviceId){$where[]='bc.service_id=?';$params[]=$serviceId;}if(in_array($currency,['CLP','USD','BRL'],true)){$where[]='bc.currency=?';$params[]=$currency;}if($q!==''){$where[]='(c.company_name LIKE ? OR cs.name LIKE ? OR bc.description LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}
$sql="SELECT bc.*,c.company_name,c.email client_email,c.whatsapp,cs.name service_name,cs.billing_frequency,cs.billing_alert_days FROM billing_charges bc JOIN clients c ON c.id=bc.client_id JOIN client_services cs ON cs.id=bc.service_id WHERE ".implode(' AND ',$where)." ORDER BY CASE WHEN bc.status='overdue' THEN 0 ELSE 1 END,bc.due_date ASC,bc.id DESC";$st=$pdo->prepare($sql);$st->execute($params);$charges=$st->fetchAll();
$clients=$pdo->query("SELECT id,company_name,country FROM clients ORDER BY COALESCE(NULLIF(country,''),'Sin país'),company_name")->fetchAll();$totals=['CLP'=>0.0,'USD'=>0.0,'BRL'=>0.0];foreach($charges as$c)if(isset($totals[$c['currency']]))$totals[$c['currency']]+=max(0,(float)$c['amount']-(float)$c['paid_amount']);
require __DIR__.'/includes/header.php';
?>
<div class="stats-grid"><?php foreach($totals as$cur=>$total):?><div class="stat-card" style="--accent:<?=$cur==='CLP'?'#0074c7':($cur==='USD'?'#73bc25':'#ff5300')?>"><small>PENDIENTE <?=e($cur)?></small><strong><?=e(format_money($total,$cur))?></strong><span>Según los filtros actuales</span></div><?php endforeach;?></div>
<section class="panel"><div class="panel-header"><div><h2>Calendario de cobros</h2><span class="table-sub"><?=count($charges)?> registros. Al registrar un pago completo, el siguiente cobro recurrente puede generarse automáticamente.</span></div><?php if(has_permission('payments.manage')):?><a class="btn btn-primary" href="payment_form.php">+ REGISTRAR PAGO</a><?php endif;?></div><div class="panel-body"><form method="get" class="filters-wide"><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Cliente o servicio"></label><label>Vista<select name="view"><option value="all" <?=$view==='all'?'selected':''?>>Todos</option><option value="week" <?=$view==='week'?'selected':''?>>Próximos 7 días</option><option value="month" <?=$view==='month'?'selected':''?>>Próximos 30 días</option><option value="upcoming" <?=$view==='upcoming'?'selected':''?>>Todos los próximos</option><option value="overdue" <?=$view==='overdue'?'selected':''?>>Vencidos</option><option value="paid" <?=$view==='paid'?'selected':''?>>Pagados</option></select></label><label>Cliente<select name="client_id"><option value="0">Todos</option><?php foreach($clients as$c):?><option value="<?=(int)$c['id']?>" <?=$clientId===(int)$c['id']?'selected':''?>><?=e(($c['country']?:'Sin país').' · '.$c['company_name'])?></option><?php endforeach;?></select></label><label>Moneda<select name="currency"><option value="">Todas</option><?php foreach(['CLP','USD','BRL']as$cur):?><option <?=$currency===$cur?'selected':''?>><?=$cur?></option><?php endforeach;?></select></label><button class="btn btn-secondary">FILTRAR</button></form></div><div class="table-wrap"><?php if(!$charges):?><div class="empty">No hay cobros para esta vista.</div><?php else:?><table class="data-table"><thead><tr><th>Cliente / servicio</th><th>Vencimiento</th><th>Valor</th><th>Pagado</th><th>Saldo</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($charges as$c):$balance=max(0,(float)$c['amount']-(float)$c['paid_amount']);$days=days_until($c['due_date']);?><tr><td><a class="table-title" href="client_view.php?id=<?=(int)$c['client_id']?>"><?=e($c['company_name'])?></a><span class="table-sub"><?=e($c['service_name'])?> · <?=e(billing_frequency_label($c['billing_frequency']))?></span></td><td><strong><?=e(format_date($c['due_date']))?></strong><span class="table-sub"><?php if($days<0):?><?=abs((int)$days)?> días vencido<?php elseif($days===0):?>Hoy<?php else:?>En <?=(int)$days?> días<?php endif;?></span></td><td><?=e(format_money($c['amount'],$c['currency']))?></td><td><?=e(format_money($c['paid_amount'],$c['currency']))?></td><td><strong><?=e(format_money($balance,$c['currency']))?></strong></td><td><span class="badge badge-<?=e(billing_charge_status_class($c['status']))?>"><?=e(billing_charge_status_label($c['status']))?></span></td><td><div class="actions"><?php if(has_permission('payments.manage')&&!in_array($c['status'],['paid','cancelled'],true)):?><a class="btn btn-primary btn-small" href="payment_form.php?charge_id=<?=(int)$c['id']?>">Registrar pago</a><?php endif;?><?php if(has_permission('billing.charges.manage')&&!in_array($c['status'],['paid','cancelled'],true)):?><form method="post" action="billing_charge_action.php" style="display:inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$c['id']?>"><input type="hidden" name="action" value="cancel"><button class="btn btn-light btn-small" data-confirm="¿Cancelar este cobro?">Cancelar</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
